  void InitializeFolderEditor(){
   folderEditPanel=new StudioPanel{Name="Ordnerbearbeitung",Tag="StudioExact"};folderEditName=new StudioTextBox{Tag="StudioExact",BorderStyle=BorderStyle.FixedSingle,BackColor=StudioDrawing.Hex("#29263B"),ForeColor=Color.White,Font=StudioDrawing.Font(14)};folderEditNumber=new StudioTextBox{Tag="StudioExact",BorderStyle=BorderStyle.FixedSingle,BackColor=StudioDrawing.Hex("#29263B"),ForeColor=Color.White,Font=StudioDrawing.Font(14)};folderEditNameLabel=TextLabel("Ordnername",12);folderEditNumberLabel=TextLabel("Ordnernummer",12);folderEditName.AccessibleName="Ordnername";folderEditNumber.AccessibleName="Ordnernummer";
   folderSaveButton=new StudioActionButton{Text="Ordner speichern",Primary=true};
   folderEditPanel.Controls.Add(folderEditNameLabel);folderEditPanel.Controls.Add(folderEditNumberLabel);folderEditPanel.Controls.Add(folderEditName);folderEditPanel.Controls.Add(folderEditNumber);folderEditPanel.Controls.Add(folderSaveButton);
   folderSaveButton.Click+=(sender,args)=>{if(!loadingFolderEditor&&FolderSaveRequested!=null)FolderSaveRequested(selectedFolderPath,folderEditName.Text,folderEditNumber.Text);};
   rightScroll.Controls.Add(folderEditPanel);
  }
  void UpdateFolderEditor(){
   if(folderEditPanel==null)return;loadingFolderEditor=true;try{
    string name=selectedFolderName??"";var match=System.Text.RegularExpressions.Regex.Match(name,@"^(\d{3})\s+(.+)$");
    folderEditNumber.Text=match.Success?match.Groups[1].Value:"";
    folderEditName.Text=match.Success?match.Groups[2].Value:name;
   }finally{loadingFolderEditor=false;}
  }
  string selectedFolderName,selectedFolderPath;Image selectedFolderArtwork;
  void RefreshFolderArtwork(string path){
   if(String.Equals(selectedFolderPath,path,StringComparison.OrdinalIgnoreCase))return;
   selectedFolderArtwork?.Dispose();selectedFolderArtwork=null;
   if(String.IsNullOrWhiteSpace(path)||!Directory.Exists(path))return;
   foreach(string file in new[]{"folder.jpg","folder.png","cover.jpg","cover.png","front.jpg","front.png"}){
    string candidate=Path.Combine(path,file);if(!File.Exists(candidate))continue;
    try{using(var source=Image.FromFile(candidate))selectedFolderArtwork=new Bitmap(source);break;}catch(IOException){}catch(ArgumentException){}
   }
  }
  public void SetCurrentFolder(string name,string path,Image artwork=null){RefreshFolderArtwork(path);selectedFolderName=name;selectedFolderPath=path;UpdateFolderEditor();if(artwork!=null){selectedFolderArtwork?.Dispose();selectedFolderArtwork=new Bitmap(artwork);}RefreshStudioNow();}
