  sealed class PageChange:IDisposable {MainView view;public PageChange(MainView view){this.view=view;}public void Dispose(){if(view!=null){var old=view;view=null;old.EndStudioPageChange();}}}
  public IDisposable BeginStudioPageChange(string page){if(studioSwitchDepth++==0){studioRedraw=new StudioRedrawScope(studioCenter);pendingStudioPage=page;}return new PageChange(this);}
  void EndStudioPageChange(){if(--studioSwitchDepth>0)return;studioCommitting=true;try{ApplyStudioPage(pendingStudioPage??studioPage);LayoutStudio();}finally{studioCommitting=false;pendingStudioPage=null;if(studioRedraw!=null){studioRedraw.Dispose();studioRedraw=null;}}}
  public void SelectStudioPage(string page){if(studioSwitchDepth>0){pendingStudioPage=page;return;}if(studioPage==page)return;using(BeginStudioPageChange(page)){} }
  void ApplyStudioPage(string page){studioPage=page;foreach(var pair in studioNav){var b=(StudioActionButton)pair.Value;bool active=pair.Key==page;if(b.Active!=active){b.Active=active;b.Invalidate();}}settingsPage=new[]{"Export","Statistiken","Wiedergabelisten","Einstellungen"}.Contains(page);bool library=page=="Bibliothek";studioLibrary.Visible=!settingsPage;ModuleHost.Visible=!library;}
  Action<string[]> moduleFilesDropped;
  public void ShowModule(Control content,Action<string[]> filesDropped=null){
   // Theme the complete tree before parenting can create or show native handles.
   content.Visible=false;ModernTheme.Apply(content);content=new StudioModuleScroll(content);ModernTheme.Apply(content);content.Dock=DockStyle.Fill;
   var old=ModuleHost.Controls.Cast<Control>().ToArray();ModuleHost.SuspendLayout();
   try{moduleFilesDropped=filesDropped;ModuleHost.Controls.Add(content);content.BringToFront();ModuleHost.Visible=true;studioLibrary.Visible=!settingsPage;LayoutStudio();content.Visible=true;foreach(Control child in content.Controls)if(!(child is StudioScrollRail))child.Visible=true;foreach(var item in old){ModuleHost.Controls.Remove(item);item.Dispose();}}
   finally{ModuleHost.ResumeLayout(true);}
  }
