  void RestoreStudioLayout(){foreach(var pane in Panes){pane.DockBack();pane.ShowPane();}LayoutStudio();}
  void SaveStudioColumns(){try{Directory.CreateDirectory(PortablePaths.Data);File.WriteAllLines(Path.Combine(PortablePaths.Data,"Spalten-Studio.tsv"),Songs.Columns.Cast<DataGridViewColumn>().Select(c=>c.Name+"\t"+c.DisplayIndex+"\t"+c.Width+"\t"+c.Visible));}catch{}}
  void LoadStudioColumns(){try{string path=Path.Combine(PortablePaths.Data,"Spalten-Studio.tsv");if(!File.Exists(path))return;restoringStudio=true;foreach(string line in File.ReadAllLines(path).OrderBy(x=>Int32.Parse(x.Split('\t')[1]))){var a=line.Split('\t');if(a.Length!=4||!Songs.Columns.Contains(a[0]))continue;var c=Songs.Columns[a[0]];int index,width;if(Int32.TryParse(a[1],out index))c.DisplayIndex=Math.Max(0,Math.Min(Songs.Columns.Count-1,index));if(Int32.TryParse(a[2],out width))c.Width=Math.Max(42,Math.Min(1000,width));bool visible;if(Boolean.TryParse(a[3],out visible))c.Visible=visible;}}catch{}finally{restoringStudio=false;}}
 }
